const body = $json.body ?? {};
const question = (body.question ?? '').toString().trim();
if (!question) {
  throw new Error("Request body must contain a 'question' field");
}
return [{
  json: {
    id: $execution.id,
    question,
    started_at: Date.now(),
  },
}];

// The Agent node does not expose exact token usage, so we estimate it
// with the common ~4 characters/token heuristic. The evaluation notebooks
// use exact usage from the OpenAI API instead (see README, Monitoring).
const MODEL = 'gpt-5.4-mini';
const PRICE_PER_1M = { input: 0.15, output: 0.6 }; // USD - adjust to your model

const prep = $('Prepare Input').first().json;
const out = $input.first().json;
const answer = (out.output ?? out.text ?? '').toString();

// system message + ~5 retrieved chunks of ~900 chars
const SYSTEM_AND_CONTEXT_CHARS = 1200 + 5 * 900;
const promptTokens = Math.ceil((prep.question.length + SYSTEM_AND_CONTEXT_CHARS) / 4);
const completionTokens = Math.ceil(answer.length / 4);
const cost =
  (promptTokens * PRICE_PER_1M.input + completionTokens * PRICE_PER_1M.output) / 1e6;

return [{
  json: {
    id: prep.id,
    question: prep.question,
    answer,
    model: MODEL,
    latency_ms: Date.now() - prep.started_at,
    prompt_tokens: promptTokens,
    completion_tokens: completionTokens,
    total_tokens: promptTokens + completionTokens,
    cost_usd: Number(cost.toFixed(6)),
  },
}];

